program JosephusProblem;

type
  NodePtr = ^Node;
  Node = record
    value: integer;
    next: NodePtr;
  end;

var
  n, k, i: integer;
  head, curr, prev, tmp: NodePtr;

begin
  write('Введите N: ');
  readln(n);
  write('Введите K: ');
  readln(k);

  { Создаем циклический список}
  new(head);
  head^.value := 1;
  curr := head;
  for i := 2 to n do
  begin
    new(tmp);
    tmp^.value := i;
    curr^.next := tmp;
    curr := tmp;
  end;
  curr^.next := head;

  curr := head;
  prev := curr;
  i := 1;

  { Удаляем каждого k-го ребенка }
  while curr^.next <> curr do
  begin
    if i = k then
    begin
      writeln(curr^.value);
      prev^.next := curr^.next;
      dispose(curr);
      curr := prev^.next;
      i := 1;
    end
    else
    begin
      prev := curr;
      curr := curr^.next;
      i := i + 1;
    end;
  end;

  { Выводим последнего ребенка }
  writeln(curr^.value);

  dispose(curr);
end. 

Данная программа использует циклический список, чтобы представить круг из ребят. Она начинает отсчет с первого ребенка и удаляет каждого k-го, пока не останется только один. Для каждого удаленного ребенка программа выводит его номер. После того, как удалены все кроме одного ребенка, программа выводит номер оставшегося ребенка.

