#include <vector>
#include <cmath>

struct Signal{
    double power_dbm;
    double frequency;
    double bandwidth;
};

class SpectrumGenerator{
public:
    SpectrumGenerator(double start_freq, double end_freq, double sample_rate,
                      double noise_floor_dbm, double noise_stddev,
                      const std::vector<Signal>& signals);

    std::vector<double> generateSpectrum() const;

private:
    double m_start_freq;
    double m_end_freq;
    double m_sample_rate;
    double m_noise_floor_dbm;
    double m_noise_stddev;
    std::vector<Signal> m_signals;
    std::vector<double> m_noise_spectrum;

    double noisePower(double freq) const;
    double signalPower(double freq) const;
    double complexSpectrum(double freq, double phase) const;
    double powerSpectrum(double freq, double phase) const;
};
```

Class implementation:

```
SpectrumGenerator::SpectrumGenerator(double start_freq, double end_freq,
                                      double sample_rate, double noise_floor_dbm,
                                      double noise_stddev,
                                      const std::vector<Signal>& signals)
    : m_start_freq(start_freq), m_end_freq(end_freq), m_sample_rate(sample_rate),
      m_noise_floor_dbm(noise_floor_dbm), m_noise_stddev(noise_stddev),
      m_signals(signals)
{
    // generate noise floor spectrum
    int num_samples = (int)((end_freq - start_freq) / sample_rate) + 1;
    m_noise_spectrum.resize(num_samples);
    for (int i = 0; i < num_samples; ++i){
        double freq = start_freq + i * sample_rate;
        m_noise_spectrum[i] = noisePower(freq);
    }

}

std::vector<double> SpectrumGenerator::generateSpectrum() const
{
    std::vector<double> spectrum(m_noise_spectrum);   // start with noise floor spectrum

    // add signal spectra
    for (const auto& signal : m_signals){
        int num_samples = (int)(signal.bandwidth / m_sample_rate) + 1;
        double signal_power = signalPower(signal.frequency);
        double phase = 2 * M_PI * ((double)std::rand() / RAND_MAX);   // generate random phase
        for (int i = 0; i < num_samples; ++i){
            double freq = signal.frequency - signal.bandwidth / 2 + i * m_sample_rate;
            if (freq > m_start_freq && freq < m_end_freq){
                double signal_spectrum = powerSpectrum(freq, phase);
                spectrum[(int)((freq - m_start_freq) / m_sample_rate)] += signal_spectrum;
            }
        }
    }

    // convert to dBm and logarithmic scale
    for (double& value : spectrum){
        value = 10 * std::log10(value) + 30;
    }

    return spectrum;
}

double SpectrumGenerator::noisePower(double freq) const
{
    double noise = m_noise_floor_dbm + m_noise_stddev * ((double)std::rand() / RAND_MAX - 0.5);
    return std::pow(10, noise/10) * std::pow(freq, 2);
}

double SpectrumGenerator::signalPower(double freq) const
{
    for (const auto& signal : m_signals){
        if (std::abs(signal.frequency - freq) <= signal.bandwidth / 2){
            return std::pow(10, signal.power_dbm/10) * std::pow(signal.bandwidth, 2);
        }
    }
    return 0;
}

double SpectrumGenerator::complexSpectrum(double freq, double phase) const
{
    return std::cos(2 * M_PI * freq / m_sample_rate + phase) +
           std::sin(2 * M_PI * freq / m_sample_rate + phase) * std::complex<double>(0, 1);
}

double SpectrumGenerator::powerSpectrum(double freq, double phase) const
{
    std::complex<double> complex_spectrum = complexSpectrum(freq, phase);
    return std::pow(std::abs(complex_spectrum), 2);
}
```

