#ifndef DSSS_H
#define DSSS_H

#include <vector>

class DSSS
{
public:
    DSSS(double chip_rate, double data_rate, const std::vector<double>& data);

    std::vector<double> modulate();
    std::vector<double> demodulate(const std::vector<double>& received_signal);

private:
    double m_chip_rate;
    double m_data_rate;
    std::vector<double> m_data;
    std::vector<double> m_chips;

    std::vector<double> generateChips(const std::vector<bool>& code) const;
    std::vector<bool> encodeData() const;
    std::vector<bool> decodeData(const std::vector<bool>& received_code) const;
};

#endif // DSSS_H
```

Class implementation:

```
#include "dsss.h"
#include <cmath>

DSSS::DSSS(double chip_rate, double data_rate, const std::vector<double>& data)
    : m_chip_rate(chip_rate), m_data_rate(data_rate), m_data(data)
{
    // generate chips from data
    int num_chips = (int)(m_chip_rate / m_data_rate);
    std::vector<bool> code = encodeData();
    m_chips = generateChips(code);
}

std::vector<double> DSSS::modulate()
{
    std::vector<double> signal;
    double chip_duration = 1 / m_chip_rate;

    for (int i = 0; i < m_chips.size(); ++i){
        // generate I and Q components for each chip
        double I = 1 / std::sqrt(2) * std::cos(2 * M_PI * i * chip_duration);
        double Q = 1 / std::sqrt(2) * std::sin(2 * M_PI * i * chip_duration);

        // multiply I and Q by the chip value and add to the signal
        signal.push_back(I * m_chips[i]);
        signal.push_back(Q * m_chips[i]);
    }

    return signal;
}

std::vector<double> DSSS::demodulate(const std::vector<double>& received_signal)
{
    std::vector<double> decoded_signal;
    double chip_duration = 1 / m_chip_rate;

    for (int i = 0; i < m_chips.size(); ++i){
        // generate I and Q components for each chip
        double I = 1 / std::sqrt(2) * std::cos(2 * M_PI * i * chip_duration);
        double Q = 1 / std::sqrt(2) * std::sin(2 * M_PI * i * chip_duration);

        // multiply I and Q by the received signal and sum
        double I_sum = 0, Q_sum = 0;
        for (int j = 0; j < received_signal.size(); j += 2){
            I_sum += received_signal[j] * I;
            Q_sum += received_signal[j+1] * Q;
        }

        // compute the chip value and append to decoded signal
        double chip = I_sum - Q_sum;
        decoded_signal.push_back(chip);
    }

    // decode data from chips and return
    std::vector<bool> received_code;
    for (const auto& chip : decoded_signal){
        received_code.push_back(chip > 0);
    }
    return decodeData(received_code);
}

std::vector<bool> DSSS::encodeData() const
{
    std::vector<bool> code;
    for (const auto& bit : m_data){
        for (int i = 0; i < (int)(m_chip_rate / m_data_rate); ++i){
            code.push_back(bit > 0);
        }
    }
    return code;
}

std::vector<double> DSSS::generateChips(const std::vector<bool>& code) const
{
    // generate chips from code using barker code
    std::vector<double> barker_code = {-1, 1, 1, 1, -1, 1, -1, -1};
    std::vector<double> chips;
    int barker_idx = 0;
    for (const auto& bit : code){
        chips.push_back(bit ? barker_code[barker_idx] : -barker_code[barker_idx]);
        barker_idx = (barker_idx + 1) % barker_code.size();
    }
    return chips;
}

std::vector<bool> DSSS::decodeData(const std::vector<bool>& received_code) const
{
    // decode data by averaging each group of chips
    std::vector<bool> decoded_data;
    for (int i = 0; i < received_code.size(); i += (int)(m_chip_rate / m_data_rate)){
        double avg_chip = 0;
        for (int j = 0; j < (int)(m_chip_rate / m_data_rate); ++j){
            avg_chip += (received_code[i+j] ? 1 : -1);
        }
        avg_chip /= (m_chip_rate / m_data_rate);
        decoded_data.push_back(avg_chip > 0);
    }
    return decoded_data;
}
```

This `DSSS` class implements direct-sequence spread spectrum modulation and demodulation using a Barker code. The class takes the chip rate, data rate, and data to be transmitted as input. The `modulate()` method generates a modulated signal by multiplying each chip with an I and Q component generated using a sinusoidal waveform. The `demodulate()` method decodes the received signal by summing the products of the I and Q components with the received signal, and returns the decoded data. The `encodeData()`, `generateChips()`, and `decodeData()` methods are used to encode the data as a sequence of chips, generate the chips using the Barker code, and decode the received chips back into the original data bits, respectively.

Here's an example of how to use the `DSSS` class to modulate and demodulate a data signal:

```
#include <iostream>
#include "dsss.h"

int main()
{
    // data to be transmitted
    std::vector<double> data = {1, -1, 1, 1, -1, -1};

    // create DSSS object with chip rate of 1 MHz and data rate of 100 kbps
    DSSS dsss(1000000, 100000, data);

    // modulate data to generate signal
    std::vector<double> signal = dsss.modulate();

    // add noise to signal
    double noise_stddev = 0.1;
    for (double& sample : signal){
        sample += noise_stddev * ((double)std::rand() / RAND_MAX - 0.5);
    }

    // demodulate received signal to recover data
    std::vector<double> received_signal(signal);   // in practice, this would be the signal received by the receiver
    std::vector<double> decoded_signal = dsss.demodulate(received_signal);

    // print original and decoded data
    std::cout << "Original data: ";
    for (const auto& bit : data){
        std::cout << bit << " ";
    }
    std::cout << std::endl;

    std::cout << "Decoded data: ";
    for (const auto& bit : decoded_signal){
        std::cout << bit << " ";
    }
    std::cout << std::endl;

    return 0;
}
```

In this example, the `DSSS` class is used to modulate and demodulate a data signal. The data signal consists of a sequence of 1s and -1s. The `DSSS` object is created with a chip rate of 1 MHz and a data rate of 100 kbps. The `modulate()` method is used to generate a modulated signal. Noise is added to the signal using a Gaussian distribution with a standard deviation of 0.1. The `demodulate()` method is used to decode the received signal and recover the original data. The original and decoded data are printed to the console.

Here is a JavaScript library example that converts CSV input to PAIN.008.001.02 formatted XML:

```javascript
const parse = require('csv-parse/lib/sync');
const builder = require('xmlbuilder');

function csvToPain008(csv) {
  const records = parse(csv, {
    columns: true,
    skip_empty_lines: true
  });

  const pain008 = builder.create('Document', { version: '1.0', encoding: 'UTF-8' })
    .att('xmlns', 'urn:iso:std:iso:20022:tech:xsd:pain.008.001.02')
    .ele('CstmrDrctDbtInitn');

  // GrpHdr
  let grpHdr = pain008.ele('GrpHdr');
  grpHdr.ele('MsgId', 'ABCDEFG123');
  grpHdr.ele('CreDtTm', '2013-08-28T17:12:44');
  grpHdr.ele('NbOfTxs', records.length);
  grpHdr.ele('CtrlSum', '12345.67'); // Replace with the desired value
  let initgPty = grpHdr.ele('InitgPty');
  initgPty.ele('Nm', 'John Doe Corporation');
  initgPty.ele('Id')
    .ele('OrgId')
    .ele('Othr')
    .ele('Id', '0123456789').up().up().up().up();

  // PmtInf
  let pmtInf = pain008.ele('PmtInf');
  let pmtInfId = 'DOMC10000025'; // Replace with the desired value
  pmtInf.ele('PmtInfId', pmtInfId);
  pmtInf.ele('PmtMtd', 'DD');
  pmtInf.ele('BtchBookg', false);
  pmtInf.ele('NbOfTxs', records.length);
  pmtInf.ele('CtrlSum', '12.01');
  let pmtTpInf = pmtInf.ele('PmtTpInf');
  pmtTpInf.ele('SvcLvl').ele('Cd', 'NURG');
  pmtTpInf.ele('LclInstrm').ele('Prtry', 'CCD');
  pmtInf.ele('ReqdColltnDt', '2020-08-21');

  // Cdtr
  let cdtr = pmtInf.ele('Cdtr');
  cdtr.ele('Nm', 'John Doe Corporation');
  cdtr.ele('PstlAdr')
    .ele('Ctry', 'US')
    .ele('AdrLine', '999 Any Street, 13th Floor')
    .ele('AdrLine', '99999 Anytown').up().up();
  cdtr.ele('Id').ele('OrgId').ele('Othr').ele('Id', '0123456789').up().up().up().up();

  // CdtrAcct
  let cdtrAcct = pmtInf.ele('CdtrAcct').ele('Id').ele('Othr').ele('Id', '0123456789').up().up().up().up();
  cdtrAcct.ele('Ccy', 'USD');

  // CdtrAgt
  let cdtrAgt = pmtInf.ele('CdtrAgt');
  cdtrAgt.ele('FinInstnId')
    .ele('ClrSysMmbId')
    .ele('MmbId', '123456789').up().up()
    .ele('PstlAdr')
    .ele('Ctry', 'US').up().up().up();

  // DrctDbtTxInf
  records.forEach(record => {
    let drctDbtTxInf = pmtInf.ele('DrctDbtTxInf');
    drctDbtTxInf.ele('PmtId').ele('EndToEndId', record.EndToEndId).up().up();
    drctDbtTxInf.ele('InstdAmt', record.InstdAmt).att('Ccy', 'USD');

    // Add other elements according to the provided record data
  });

  const xml = pain008.end({ pretty: true });

  return xml;
}

module.exports = {
  csvToPain008
};
```

