openTime = order.time;
}

if (closeTime < order.time) {
closeTime = order.time;
}
});

drawTradeLines(
chart,
openPrice,
openTime,
closePrice,
closeTime,
orders[0].position,
paneId,
pricePrecision,
quantityPrecision,
);
}
}, [orders, candles, tradeId]);
